<script setup lang="ts">
import { onMounted,onUnmounted,ref,watch } from 'vue'
import { ElInput,ElSelect,ElOption,ElButton,ElTag,ElAlert,ElPagination } from 'element-plus'
import { API } from '../../../shared/api'
import { dateLabel,isCancelled } from '../../../shared/console'
const props=defineProps<{api:API}>();const emit=defineEmits<{source:[id:string];open:[page:string]}>()
const query=ref(''),status=ref('active'),page=ref(1),records=ref<any>(null),selected=ref<any>(null),timeline=ref<any[]>([]),error=ref(''),loading=ref(false)
let timer:ReturnType<typeof setTimeout>,alive=true
const names:Record<string,string>={fact:'事实',preference:'偏好',profile:'画像',goal:'目标',procedure:'流程'}
async function load(){loading.value=true;try{records.value=await props.api.request('/studio/memories?'+new URLSearchParams({q:query.value,status:status.value,page:String(page.value)}),undefined,'GET','memory-inventory')}catch(e){if(alive&&!isCancelled(e))error.value=(e as Error).message}finally{if(alive)loading.value=false}}
async function choose(item:any){selected.value=item;timeline.value=[];try{const result=await props.api.request('/memories/'+encodeURIComponent(item.id)+'/timeline',undefined,'GET','memory-timeline');if(alive&&selected.value?.id===item.id)timeline.value=result}catch(e){if(alive&&!isCancelled(e))error.value=(e as Error).message}}
watch([query,status],()=>{clearTimeout(timer);timer=setTimeout(()=>{page.value=1;void load()},300)})
onMounted(()=>void load());onUnmounted(()=>{alive=false;clearTimeout(timer)})
</script>
<template><el-alert v-if="error" :title="error" type="error" :closable="false"/><section class="panel"><div class="section-title"><div><h2>长期记忆库 <span class="count-label">{{ records?.total??'—' }} 条</span></h2><p>查看记忆正文、来源和状态，原始对话由历史对话入口查看。</p></div><el-button :loading="loading" @click="load">刷新</el-button></div><div class="inventory-filters"><el-input v-model="query" clearable placeholder="搜索记忆正文" maxlength="200"/><el-select v-model="status" aria-label="记忆状态"><el-option value="active" label="有效记忆"/><el-option value="superseded" label="被替代的历史"/><el-option value="all" label="全部状态"/></el-select></div><table v-if="records?.items.length" class="data-table"><thead><tr><th>记忆内容</th><th>类型</th><th>状态</th><th>重要度</th><th>更新记录</th></tr></thead><tbody><tr v-for="item in records.items" :key="item.id" @click="choose(item)" tabindex="0" @keydown.enter="choose(item)"><td class="memory-content-cell">{{ item.content }}</td><td>{{ names[item.kind]??item.kind }}</td><td><el-tag size="small">{{ item.status }}</el-tag></td><td>{{ item.importance }} / 5</td><td>{{ dateLabel(item.updated_at) }}</td></tr></tbody></table><div v-else class="empty"><span>◈</span><h3>{{ query?'没有匹配的记忆':'这个账号还没有有效记忆' }}</h3><p>已有对话不会自动等于已批准的长期记忆。你可以先阅读历史，核对适用来源后再进行审核。</p><el-button @click="emit('open','conversations')">浏览历史对话</el-button></div><el-pagination v-if="records?.total" layout="total, prev, pager, next" :total="records.total" :page-size="50" :current-page="records.page" @current-change="(p:number)=>{page=p;load()}"/></section><section v-if="selected" class="panel"><div class="section-title"><h2>记忆详情</h2><el-tag>{{ names[selected.kind]??selected.kind }}</el-tag></div><div class="source-original">{{ selected.content }}</div><dl><dt>来源</dt><dd>{{ selected.source }}</dd><dt>创建时间</dt><dd>{{ dateLabel(selected.created_at,true) }}</dd><dt>更新记录</dt><dd>{{ dateLabel(selected.updated_at,true) }}</dd><dt>强化次数</dt><dd>{{ selected.reinforcement }}</dd></dl><el-button v-if="selected.source_ref" @click="emit('source',selected.source_ref)">核对原始来源 ↗</el-button><el-button @click="emit('open','explorer')">进入结构化记忆审核</el-button><details><summary>版本时间线（原始字段）</summary><pre>{{ JSON.stringify(timeline,null,2) }}</pre></details></section></template>
